/**
 * Test: Dual Auth Architecture Verification
 * 1. Monthly Subscription -> Pure Auth Token (x-dsh-auth-token / JWT) like Antigravity. Zero API key needed.
 * 2. Deposit / Pay-As-You-Go -> Self-service API Key (sk_boson_...) generated by user for external tools/scripts.
 */

const GATEWAY_URL = process.env.GATEWAY_URL || 'http://127.0.0.1:8088'

async function registerUser(email, tier = 'free') {
  const initRes = await fetch(`${GATEWAY_URL}/auth-api/v0/dsh/auth_init`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      code_challenge: 'challenge_' + Math.random().toString(36).slice(2),
      redirect_uri: 'http://127.0.0.1:3080/callback',
      state: 'test_state',
    }),
  })
  const initData = await initRes.json()
  const authId = initData.data?.biz_data?.authorize_id

  await fetch(`${GATEWAY_URL}/api/v0/auth/submit-register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      auth_id: authId,
      email,
      password: 'Password123!',
      full_name: `User ${tier.toUpperCase()}`,
    }),
  })

  const exchangeRes = await fetch(`${GATEWAY_URL}/auth-api/v0/dsh/auth_exchange`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ authorize_id: authId }),
  })
  const exchangeData = await exchangeRes.json()
  const token = exchangeData.data?.biz_data?.token
  const userId = exchangeData.data?.biz_data?.user?.id

  return { token, userId, email }
}

async function runTest() {
  console.log('=== STARTING DUAL-AUTH ARCHITECTURE VERIFICATION ===\n')

  // -------------------------------------------------------------
  // TRACK 1: MONTHLY SUBSCRIPTION (AUTH TOKEN ONLY - ZERO API KEY)
  // -------------------------------------------------------------
  console.log('--- TRACK 1: Monthly Subscription via Auth Token (Antigravity Style) ---')
  const subEmail = `subs_${Date.now()}@boson.id`
  const subUser = await registerUser(subEmail, 'pro')
  console.log(`[Track 1] Registered Subscriber: ${subEmail} (User ID: ${subUser.userId})`)
  console.log(`[Track 1] Auth Token acquired: ${subUser.token.slice(0, 16)}... (NO API KEY GENERATED)`)

  // Upgrade to Pro tier with $10.00 subscription balance
  await fetch(`${GATEWAY_URL}/api/v0/billing/test-topup`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-dsh-auth-token': subUser.token,
    },
    body: JSON.stringify({
      user_id: subUser.userId,
      tier: 'pro',
      subscription_balance: 10.0,
      normal_balance: 0.0,
      bonus_balance: 0.0,
    }),
  })

  // Check wallet before
  const subWalletBefore = await fetch(`${GATEWAY_URL}/v1/quota`, {
    headers: { 'x-dsh-auth-token': subUser.token },
  }).then(r => r.json())
  console.log(`[Track 1] Wallet before: Subscription Balance = $${subWalletBefore.subscription_balance}`)

  // Call Chat Completion using ONLY x-dsh-auth-token (Simulating Antigravity / App Client)
  const chatSubRes = await fetch(`${GATEWAY_URL}/v1/chat/completions`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-dsh-auth-token': subUser.token,
      'x-mock-dummy': 'true',
    },
    body: JSON.stringify({
      model: 'claude-3-5-sonnet',
      messages: [{ role: 'user', content: 'Generate code for payment verification' }],
    }),
  })

  const chatSubData = await chatSubRes.json()
  console.log(`[Track 1] Chat Status: ${chatSubRes.status} (OK: ${chatSubRes.ok})`)
  if (!chatSubRes.ok) {
    console.error('[Track 1] Error:', chatSubData)
    process.exit(1)
  }

  // Check wallet after
  const subWalletAfter = await fetch(`${GATEWAY_URL}/v1/quota`, {
    headers: { 'x-dsh-auth-token': subUser.token },
  }).then(r => r.json())
  console.log(`[Track 1] Wallet after: Subscription Balance = $${subWalletAfter.subscription_balance}`)
  const subCost = subWalletBefore.subscription_balance - subWalletAfter.subscription_balance
  console.log(`[Track 1] Successfully debited from Subscription Balance: $${subCost.toFixed(6)}`)
  console.log(`[Track 1] SUCCESS: Monthly subscriber performed inference purely via session auth token! Zero raw API keys required.\n`)

  // -------------------------------------------------------------
  // TRACK 2: DEPOSIT / PAY-AS-YOU-GO (SELF-GENERATED API KEY)
  // -------------------------------------------------------------
  console.log('--- TRACK 2: Deposit / Pay-As-You-Go via Self-Generated API Key (Developer Mode) ---')
  const devEmail = `dev_${Date.now()}@boson.id`
  const devUser = await registerUser(devEmail, 'deposit')
  console.log(`[Track 2] Registered Developer: ${devEmail} (User ID: ${devUser.userId})`)

  // Top-up deposit balance ($5.00)
  await fetch(`${GATEWAY_URL}/api/v0/billing/test-topup`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-dsh-auth-token': devUser.token,
    },
    body: JSON.stringify({
      user_id: devUser.userId,
      tier: 'pay_as_you_go',
      normal_balance: 5.0,
      subscription_balance: 0.0,
      bonus_balance: 0.0,
    }),
  })

  // Developer generates their own API Key via self-service endpoint POST /api/v0/api-keys
  const genKeyRes = await fetch(`${GATEWAY_URL}/api/v0/api-keys`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-dsh-auth-token': devUser.token,
    },
    body: JSON.stringify({
      key_name: 'Cursor & Python CLI Pipeline Key',
      allowed_platforms: ['*'],
      target_app_id: '*',
    }),
  })
  const genKeyData = await genKeyRes.json()
  const apiKey = genKeyData.api_key
  console.log(`[Track 2] Generated Personal API Key: ${apiKey.slice(0, 16)}...`)

  // Check wallet before
  const devWalletBefore = await fetch(`${GATEWAY_URL}/v1/quota`, {
    headers: { 'x-dsh-auth-token': devUser.token },
  }).then(r => r.json())
  console.log(`[Track 2] Wallet before: Deposit Normal Balance = $${devWalletBefore.deposit_balance ?? devWalletBefore.normal_balance}`)

  // Call Chat Completion using ONLY the generated Bearer sk_boson_... (Simulating external script / Cursor)
  const chatDevRes = await fetch(`${GATEWAY_URL}/v1/chat/completions`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
      'x-mock-dummy': 'true',
    },
    body: JSON.stringify({
      model: 'deepseek-chat',
      messages: [{ role: 'user', content: 'Explain architectural separation of concerns' }],
    }),
  })

  const chatDevData = await chatDevRes.json()
  console.log(`[Track 2] Chat Status: ${chatDevRes.status} (OK: ${chatDevRes.ok})`)
  if (!chatDevRes.ok) {
    console.error('[Track 2] Error:', chatDevData)
    process.exit(1)
  }

  // Check wallet after
  const devWalletAfter = await fetch(`${GATEWAY_URL}/v1/quota`, {
    headers: { 'x-dsh-auth-token': devUser.token },
  }).then(r => r.json())
  const devBalAfter = devWalletAfter.deposit_balance ?? devWalletAfter.normal_balance
  const devBalBefore = devWalletBefore.deposit_balance ?? devWalletBefore.normal_balance
  console.log(`[Track 2] Wallet after: Deposit Normal Balance = $${devBalAfter}`)
  const devCost = devBalBefore - devBalAfter
  console.log(`[Track 2] Successfully debited from Deposit Balance: $${devCost.toFixed(6)}`)
  console.log(`[Track 2] SUCCESS: Developer performed inference with their own self-generated API Key debited from deposit wallet!\n`)

  console.log('=== ALL ARCHITECTURAL TESTS PASSED (100% SUCCESS) ===')
}

runTest().catch(err => {
  console.error('Fatal Test Failure:', err)
  process.exit(1)
})
